import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.Czhw_PXq.js";const p=JSON.parse('{"title":"ADR 031: Auth Header Fallback Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adr/031-auth-header-fallback.md","filePath":"adr/031-auth-header-fallback.md"}'),n={name:"adr/031-auth-header-fallback.md"};function r(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-031-auth-header-fallback-strategy" tabindex="-1">ADR 031: Auth Header Fallback Strategy <a class="header-anchor" href="#adr-031-auth-header-fallback-strategy" aria-label="Permalink to &quot;ADR 031: Auth Header Fallback Strategy&quot;">​</a></h1><p>Date: 2026-03-04</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The application uses an HTTP-only cookie strategy for authentication to enhance security and prevent XSS attacks from easily stealing tokens. However, in certain cloud deployment environments (specifically Render) and cross-domain scenarios, strict browser cookie policies (SameSite, Secure) can prevent cookies from being reliably sent to the backend.</p><p>This resulted in a critical issue where validly logged-in users were not redirected to the dashboard because the frontend API calls failed to authenticate, despite the presence of a valid session.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have decided to implement a <strong>Hybrid Authentication Strategy</strong> in the frontend:</p><ol><li><strong>Primary Method</strong>: Continue to use HTTP-only cookies for persistence and security.</li><li><strong>Fallback Method</strong>: Explicitly include the <code>Authorization: Bearer &lt;token&gt;</code> header in all API requests made by the frontend service.</li><li><strong>Token Storage</strong>: The <code>auth_token</code> is stored in <code>localStorage</code> upon successful login (in addition to the cookie being set). This token is retrieved and added to the headers of subsequent requests.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Reliability</strong>: Authentication works reliably across different hosting environments and domain configurations (e.g., frontend on Netlify/Vercel, backend on Render).</li><li><strong>Resilience</strong>: Users are not blocked from using the application if their browser or network environment strips cookies.</li><li><strong>Compatibility</strong>: Aligns with standard JWT-based authentication patterns while keeping the security benefits of cookies where possible.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Redundancy</strong>: The token is sent twice (in cookie and header) when cookies are working correctly.</li><li><strong>XSS Risk</strong>: Storing the token in <code>localStorage</code> makes it accessible to JavaScript, theoretically increasing exposure to XSS attacks compared to <em>only</em> using HTTP-only cookies. However, this is a standard industry compromise for SPA architectures, and we verify XSS mitigation via other means (sanitization, CSP).</li></ul><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><ul><li>Modified <code>frontend/src/services/api.ts</code> to retrieve <code>auth_token</code> from <code>localStorage</code>.</li><li>Updated <code>getFetchOptions</code>, <code>uploadTender</code>, and <code>validateProposal</code> to include <code>Authorization: Bearer ${token}</code>.</li></ul>',17)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
